code='''def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    from collections import Counter
    counts = Counter(x for row in a for x in row)
    bg = counts.most_common(1)[0][0]

    # Boundary bars emit perpendicular rays at offsets indicated by interior marks.
    runs = []  # (orientation, start, end, edge, color); end is exclusive
    for edge in (('v', 0), ('v', w - 1), ('h', 0), ('h', h - 1)):
        orient, fixed = edge
        n = h if orient == 'v' else w
        def cell(i):
            return a[i][fixed] if orient == 'v' else a[fixed][i]
        i = 0
        while i < n:
            color = cell(i)
            j = i + 1
            while j < n and cell(j) == color:
                j += 1
            if color != bg and j - i >= 2:
                runs.append((orient, i, j, fixed, color))
            i = j

    # Interior colored cells mark which offsets are active on the boundary bars.
    marks = []
    for r in range(h):
        for c in range(w):
            if a[r][c] != bg and r not in (0, h - 1) and c not in (0, w - 1):
                marks.append((r, c, a[r][c]))
    if not runs or not marks:
        return a
    mark_color = Counter(v for _, _, v in marks).most_common(1)[0][0]

    offsets = set()
    for r, c, v in marks:
        for orient, start, end, fixed, edge_color in runs:
            pos = r if orient == 'v' else c
            if start <= pos < end and v != edge_color:
                offsets.add(pos - start)

    if not offsets:
        return a
    for orient, start, end, fixed, edge_color in runs:
        for off in sorted(offsets):
            if off >= end - start:
                continue
            pos = start + off
            if orient == 'v':
                r = pos
                # Ray from the side bar inward; a mark stops and caps the ray.
                seeds = [(c, v) for rr, c, v in marks if rr == r and v != edge_color]
                if fixed == 0:
                    stop = min((c for c, _ in seeds), default=w)
                    for c in range(1, min(stop, w - 1)):
                        a[r][c] = mark_color
                else:
                    stop = max((c for c, _ in seeds), default=-1)
                    for c in range(max(stop + 1, 1), w - 1):
                        a[r][c] = mark_color
                for c, v in seeds:
                    a[r][c] = 4
            else:
                c = pos
                seeds = [(r, v) for r, cc, v in marks if cc == c and v != edge_color]
                if fixed == 0:
                    stop = min((r for r, _ in seeds), default=h)
                    for r in range(1, min(stop, h - 1)):
